fn binary_search(a: &Vec<i32>, key: i32) -> usize {
    // We maintain a half-open search window [lo, hi)
    // Invariants:
    //   0 <= lo <= hi <= a.len()
    //   All indices < lo have a[i] < key
    //   All indices >= hi have a[i] >= key
    let mut lo = 0;
    let mut hi = a.len();

    while lo < hi {
        // Avoid potential overflow
        let mid = lo + (hi - lo) / 2;
        if a[mid] < key {
            // key must be inserted strictly after mid
            lo = mid + 1;
        } else {
            // key could be inserted at mid or before
            hi = mid;
        }
    }

    // lo == hi is the insertion point
    lo
}

